CREATE TABLE IF NOT EXISTS engagement_catalog (slug text PRIMARY KEY CHECK (slug ~ '^[a-z0-9-]{1,80}$'), name text NOT NULL, category text NOT NULL);
CREATE TABLE IF NOT EXISTS engagement_events (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, event_type text NOT NULL CHECK(event_type IN ('first_visit','return_visit','search_match','search_no_match','create','copy','open_chat','save','share','tool_run')), slug text NOT NULL CHECK(slug ~ '^[a-z0-9-]{1,80}$'), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS engagement_events_time_idx ON engagement_events(created_at);
CREATE INDEX IF NOT EXISTS engagement_events_slug_type_idx ON engagement_events(slug,event_type,created_at);
CREATE TABLE IF NOT EXISTS community_agents (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, name text NOT NULL CHECK(length(name) BETWEEN 3 AND 80), creator text NOT NULL CHECK(length(creator) BETWEEN 2 AND 40), task text NOT NULL CHECK(length(task) BETWEEN 20 AND 1500), provider text NOT NULL CHECK(provider IN ('chatgpt','claude','gemini')), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS community_status_time_idx ON community_agents(status,created_at);
CREATE OR REPLACE VIEW engagement_daily AS SELECT created_at::date AS day,slug,event_type,count(*) AS events FROM engagement_events GROUP BY 1,2,3;
CREATE OR REPLACE VIEW engagement_popular AS SELECT c.slug,c.name,c.category,count(e.id) FILTER(WHERE e.event_type='search_match') AS search_matches,count(e.id) FILTER(WHERE e.event_type='copy') AS copies,count(e.id) FILTER(WHERE e.event_type='open_chat') AS chat_opens,count(e.id) FILTER(WHERE e.event_type='create') AS requests_created,count(e.id) FILTER(WHERE e.event_type='save') AS saves FROM engagement_catalog c LEFT JOIN engagement_events e ON c.slug=e.slug GROUP BY c.slug,c.name,c.category;

ALTER TABLE engagement_events ADD COLUMN IF NOT EXISTS source text CHECK(source IN ('chatgpt','perplexity','gemini','claude','copilot','google','bing','other_referral','direct_or_unknown'));
ALTER TABLE engagement_events ADD COLUMN IF NOT EXISTS landing_kind text CHECK(landing_kind IN ('home','builder','listing','directory','guide','other'));
CREATE OR REPLACE VIEW engagement_search_referrals AS SELECT created_at::date AS day,source,landing_kind,slug,count(*) AS visits FROM engagement_events WHERE event_type IN ('first_visit','return_visit') AND source IS NOT NULL GROUP BY 1,2,3,4;
